  std::vector<int> get_unique_coords(const std::vector<Fish>& mackerels, int axis) {
      // axis=0 for x, axis=1 for y
      std::map<int, int> counts;
      for (auto& f : mackerels) {
          if (axis == 0) counts[f.p.x]++;
          else counts[f.p.y]++;
      }
      std::vector<int> result(counts.size());
      int i = 0;
      for (auto& p : counts) result[i++] = p.first;
      return result;
  }

  std::vector<Point> build_bounding_box(const std::vector<Fish>& mackerels) {
      int min_x = 100000, max_x = 0, min_y = 100000, max_y = 0;
      for (auto& f : mackerels) {
          min_x = min(min_x, f.p.x); max_x = max(max_x, f.p.x);
          min_y = min(min_y, f.p.y); max_y = max(max_y, f.p.y);
      }
      return {{min_x,min_y}, {max_x,min_y}, {max_x,max_y}, {min_x,max_y}};
  }

  int count_fish_in_polygon(const std::vector<Point>& poly, const std::vector<Fish>& fish, int type) {
      // Point-in-polygon test for axis-aligned polygons
      // Points on edges count as inside
      int count = 0;
      for (auto& f : fish) {
          if (point_in_polygon(f.p, poly)) {
              count += (type == 1 ? 1 : -1);
          }
      }
      return std::max(0, count + 1);
  }
  ```

